require dirname(__DIR__).'/app/bootstrap.php';require_login();require dirname(__DIR__).'/app/layout.php';$q=mb_substr(trim($_GET['q']??''),0,100);page_start('Search','Find the people, records and opportunities that matter.');?><form class="list-toolbar"><div class="list-search"><?= icon('search') ?><input name="q" value="<?= e($q) ?>" type="search" placeholder="Search your business..." required aria-label="Search your business"></div><button class="btn primary">Search</button></form><?php if(mb_strlen($q)>=2):foreach(modules() as $module=>$def):if(!can($module.'.view'))continue;$column=$module==='tasks'?'title':($module==='expenses'?'description':'name');$found=rows("SELECT id,$column label FROM $module WHERE business_id=? AND $column LIKE ? LIMIT 20",[bid(),'%'.$q.'%']);if(!$found)continue;?><section class="panel search-results"><h2><?= e($def['title']) ?></h2><?php foreach($found as $r): ?><a href="<?= e($module==='customers'?'customer-view.php?id='.$r['id']:$module.'.php?'.(can($module.'.edit')?'edit='.$r['id']:'q='.rawurlencode($r['label']))) ?>"><?= e($r['label']) ?><?= icon('arrow-up-right') ?></a><?php endforeach; ?></section><?php endforeach;foreach(['invoice'=>'invoices','quotation'=>'quotations'] as $type=>$perm):if(!can($perm.'.view'))continue;$found=list_documents($type,$q,20);if(!$found)continue;?><section class="panel search-results"><h2><?= ucfirst($perm) ?></h2><?php foreach($found as $r): ?><a href="invoice-view.php?id=<?= $r['id'] ?>"><?= e($r['number'].' · '.$r['customer_name']) ?><?= icon('arrow-up-right') ?></a><?php endforeach; ?></section><?php endforeach;else: ?><div class="empty"><h2>A little more to go on?</h2><p>Enter at least two characters to search your authorized records.</p></div><?php endif;page_end(); ?>
